export type MessageKey = keyof typeof en | keyof typeof accountEn;
const dictionaries: Record<Locale,Record<MessageKey,string>> = {en:{...en,...accountEn},zh:{...zh,...accountZh},ja:{...ja,...accountJa}};
export const languages: { id: Locale; label: string }[] = [{id:'zh',label:'中文'},{id:'en',label:'English'},{id:'ja',label:'日本語'}];
export function translate(locale: Locale, key: MessageKey, values: Record<string,string|number> = {}) { let s = dictionaries[locale][key]; for (const [k,v] of Object.entries(values)) s=s.replaceAll(`{${k}}`,String(v)); return s; }
export function localize(value: Partial<Record<Locale,string>> | undefined, locale: Locale): string { return value?.[locale]?.trim() || value?.zh?.trim() || value?.en?.trim() || value?.ja?.trim() || translate(locale,'missingContent'); }
